const http = require("http");
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const express = require("express");
const dotenv = require("dotenv");
const bs58 = require("bs58");
const WebSocket = require("ws");
const {
  Connection,
  Keypair,
  PublicKey,
  Transaction,
} = require("@solana/web3.js");
const {
  getAssociatedTokenAddress,
  createTransferInstruction,
} = require("@solana/spl-token");

dotenv.config();

const PORT = process.env.PORT || 3000;

const INDEX_A = path.join(__dirname, "public", "index.html");
const INDEX_B = path.join(__dirname, "index.html");

function readIndex() {
  if (fs.existsSync(INDEX_A)) return fs.readFileSync(INDEX_A);
  if (fs.existsSync(INDEX_B)) return fs.readFileSync(INDEX_B);
  return null;
}

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

const app = express();
app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const IRONWAKE_MINT = new PublicKey(
  "8dDgbMKXpMXaAEmwkSCrzChrCQFT5nLMZ9BD4FGE2gR9"
);
const MAX_REWARD = 50000;
const IRONWAKE_DECIMALS = 9;

let treasuryKeypair = null;
let connection = null;

function getTreasuryKeypair() {
  if (treasuryKeypair) return treasuryKeypair;
  if (!process.env.TREASURY_PRIVATE_KEY) {
    throw new Error("TREASURY_PRIVATE_KEY is not set");
  }
  treasuryKeypair = Keypair.fromSecretKey(
    bs58.decode(process.env.TREASURY_PRIVATE_KEY)
  );
  return treasuryKeypair;
}

function getConnection() {
  if (connection) return connection;
  if (!process.env.HELIUS_RPC) {
    throw new Error("HELIUS_RPC is not set");
  }
  connection = new Connection(process.env.HELIUS_RPC, "confirmed");
  return connection;
}

const clients = new Map(); // ws -> {id, tier, tankName, mode, roomId}
const waiting = new Map(); // key=(mode|tier) -> [ws,...]
const rooms = new Map();   // roomId -> {hostWs, sockets:[ws...], players:[{id,tankName}], mode, tier}

function needCount(mode){
  if(mode === "ONLINE2V2") return 4;
    return 2;
}
function keyOf(mode, tier){
  return `${mode}|${tier}`;
}
function send(ws, obj){
  if(ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(obj));
}

function cleanup(ws){
  const c = clients.get(ws);
  if(!c) return;

  if(c.mode && c.tier != null){
    const k = keyOf(c.mode, c.tier);
    const q = waiting.get(k);
    if(q){
      const nq = q.filter(x=>x!==ws);
      if(nq.length) waiting.set(k, nq);
      else waiting.delete(k);
    }
  }

  if(c.roomId && rooms.has(c.roomId)){
    const room = rooms.get(c.roomId);
    for(const s of room.sockets){
      if(s!==ws) send(s, {type:"info", text:"A player disconnected. Match ended."});
      try{ s.close(); }catch(_){}
    }
    rooms.delete(c.roomId);
  }

  clients.delete(ws);
}

app.get("/healthz", (req, res) => {
  res.status(200).type("text").send("ok");
});

app.get("/", (req, res) => {
  const html = readIndex();
  if (!html) {
    res
      .status(500)
      .type("text")
      .send("Missing index.html (need public/index.html or index.html at root)");
    return;
  }
  res.status(200).type("html").send(html);
});

app.post("/claim", async (req, res) => {
  try {
    console.log("CLAIM REQUEST:", req.body);
    const { wallet, amount } = req.body || {};
    const parsedAmount = typeof amount === "string" ? Number(amount.trim()) : Number(amount);
    if (
      !wallet ||
      !Number.isFinite(parsedAmount) ||
      parsedAmount <= 0 ||
      parsedAmount > MAX_REWARD
    ) {
      return res.status(400).json({ error: "Invalid request" });
    }

    const player = new PublicKey(wallet);
    const treasury = getTreasuryKeypair();
    const conn = getConnection();

    const treasuryATA = await getAssociatedTokenAddress(
      IRONWAKE_MINT,
      treasury.publicKey
    );
    const playerATA = await getAssociatedTokenAddress(IRONWAKE_MINT, player);

    const scaledAmount = Math.round(
      parsedAmount * 10 ** IRONWAKE_DECIMALS
    );
    const tx = new Transaction().add(
      createTransferInstruction(
        treasuryATA,
        playerATA,
        treasury.publicKey,
        scaledAmount
      )
    );

    tx.feePayer = player;
    tx.recentBlockhash = (await conn.getLatestBlockhash()).blockhash;
    tx.partialSign(treasury);

    res.json({
      tx: tx.serialize({ requireAllSignatures: false }).toString("base64"),
    });
  } catch (error) {
    console.error("Claim error:", error);
    res.status(500).json({ error: "Server error" });
  }
});

app.use((req, res) => {
  res.status(404).type("text").send("Not found");
});

const server = http.createServer(app);

const wss = new WebSocket.Server({ server });

wss.on("connection", (ws)=>{
  const id = uid();
  clients.set(ws, { id, tier:null, tankName:null, mode:null, roomId:null, username:"" });
  send(ws, { type:"welcome", id });

  ws.on("message", (buf)=>{
    let msg;
    try{ msg = JSON.parse(buf.toString("utf8")); }catch(_){ return; }
    const c = clients.get(ws);
    if(!c) return;

    if(msg.type === "join"){
      c.tier = Number(msg.tier || 1);
      c.tankName = String(msg.tankName || "Tank");
      c.username = String(msg.username || "").trim().slice(0,16);
      c.mode = String(msg.mode || "ONLINE1V1");

      const k = keyOf(c.mode, c.tier);
      const q = waiting.get(k) || [];
      q.push(ws);
      waiting.set(k, q);

      const need = needCount(c.mode);
      for(const s of q){
        send(s, { type:"roomInfo", roomId:null, hostId:null, players:[], text:`Searching… ${q.length}/${need} players` });
      }

      if(q.length >= need){
        const sockets = q.splice(0, need);
        if(q.length) waiting.set(k, q); else waiting.delete(k);

        const roomId = uid();
        const hostWs = sockets[0];
        const players = sockets.map(s=>{
          const cc = clients.get(s);
          return { id: cc.id, tankName: cc.tankName, username: (cc.username||"") };
        });
        for(const s of sockets) clients.get(s).roomId = roomId;

        rooms.set(roomId, { hostWs, sockets, players, mode:c.mode, tier:c.tier });

        for(const s of sockets){
          send(s, { type:"roomInfo", roomId, hostId: clients.get(hostWs).id, players, text:"Match found!" });
        }
        send(hostWs, { type:"hostStart" });
      }
      return;
    }

    if(msg.type === "input" || msg.type === "init" || msg.type === "snapshot"){
      if(!c.roomId) return;
      const room = rooms.get(c.roomId);
      if(!room) return;

      if(msg.type === "input"){
        if(room.hostWs !== ws){
          send(room.hostWs, { type:"input", fromId:c.id, payload: msg.payload || {} });
        }
        return;
      }

      if(room.hostWs === ws){
        for(const s of room.sockets){
          if(s!==ws) send(s, { type: msg.type, payload: msg.payload || {} });
        }
      }
      return;
    }
  });

  ws.on("close", ()=>cleanup(ws));
  ws.on("error", ()=>cleanup(ws));
});

